import { useQuery } from '@tanstack/react-query';
import { PaymentCalcInfoRequestDTO, PaymentCalcInfoResponseDTO } from '~/entities/voucher/api/dtos/payment-clac-info';
import { voucherApi } from '~/entities/voucher/api/voucher-api';
import { CBDCAxiosError } from '~/shared/@types/error';
import { QueryOptions } from '~/shared/@types/query';
import { queries } from '~/shared/api/query-keys';

export const usePaymentCalcQuery = (
  { tbPayMastr }: PaymentCalcInfoRequestDTO,
  options?: QueryOptions<PaymentCalcInfoResponseDTO, CBDCAxiosError>,
) => {
  return useQuery<PaymentCalcInfoResponseDTO, CBDCAxiosError>({
    queryKey: queries.voucher.paymentCalcInfo({ tbPayMastr }).queryKey,
    queryFn: () => voucherApi.getPaymentCalcInfo({ tbPayMastr }),
    ...options,
    enabled: !!tbPayMastr.vouchId && !!tbPayMastr.amt,
    throwOnError: true,
  });
};
