import { memo } from 'react';
import { VoucherItemDTO } from '~/entities/voucher/api/dtos/voucher-item';
import { useVoucherOptions } from '~/entities/voucher/lib/use-voucher-options';
import i18n from '~/shared/i18n/i18n';
import { SelectOption, SelectStyle } from '~/shared/ui/selects/base/types';
import { SelectList } from '~/shared/ui/selects/select-list';

type VoucherListProps = {
  selectedVoucher: SelectOption<VoucherItemDTO>;
  onSelectVoucher: (value: SelectOption<VoucherItemDTO>) => void;
  placeId?: string;
  aliasNm?: string | null;
};

export const VoucherList = memo(({ selectedVoucher, onSelectVoucher, placeId, aliasNm }: VoucherListProps) => {
  const { options, defaultOption } = useVoucherOptions(placeId, aliasNm);

  return (
    <div className="pay-benefit-area">
      <div className="pay-benefit-box">
        <h3>{i18n.t('selectBenefitApplication')}</h3>
        <SelectList
          options={options}
          selectedOption={selectedVoucher}
          defaultSelectedOption={defaultOption}
          onSelect={onSelectVoucher}
          selectStyle={SelectStyle.RADIO}
        />
      </div>
    </div>
  );
});

VoucherList.displayName = 'VoucherList';
