import { ErrorBoundary, Suspense } from '@suspensive/react';
import { QueryErrorResetBoundary } from '@tanstack/react-query';
import { useForm, FormProvider, Controller } from 'react-hook-form';
import { 금액확인Context } from '~/widgets/exchange-payment-funnel/model/schemas';
import { FallbackErrorMessage } from '~/widgets/fallbacks/ui/fallback-error-message';
import { LoadingSpinner } from '~/widgets/loading/loading-spinner';
import { PhaseType } from '~/entities/exchange/model/constants';
import { PaymentDetails } from '~/entities/exchange/ui/payment-details';
import { RefundPolicyInfo } from '~/entities/exchange/ui/refund-policy-info';
import { ConfirmInfo } from '~/entities/exchange-input-confirm/ui/confirm-info';
import { VoucherItemDTO } from '~/entities/voucher/api/dtos/voucher-item';
import { usePaymentCalcQuery } from '~/entities/voucher/api/hooks/use-payment-calc';
import { VoucherList } from '~/entities/voucher/ui/voucher-list';
import { getExchangeTransactionLabel } from '~/entities/wallet/lib/get-trnsc-type-label';
import i18n from '~/shared/i18n/i18n';
import { usePinBottomSheet } from '~/shared/lib/hooks/use-pin-bottom-sheet';
import { SelectOption } from '~/shared/ui/selects/base/types';

type FormValues = {
  voucherItem: SelectOption<VoucherItemDTO>;
};

type Props = {
  context: 금액확인Context;
  onNext: (params: 금액확인Context) => void;
  onError: (error: Error) => void;
};

export const InputConfirmPage = ({ context, onNext, onError }: Props) => {
  const { openPinBottomSheet } = usePinBottomSheet();

  const form = useForm<FormValues>({
    defaultValues: {
      voucherItem: null as unknown as SelectOption<VoucherItemDTO>,
    },
  });
  const vouchId = form.watch('voucherItem')?.value?.vouchId || '';

  const { data: paymentCalcInfo } = usePaymentCalcQuery({ tbPayMastr: { vouchId, amt: context.trnscAmt } });

  const handleSubmit = form.handleSubmit((data) => {
    openPinBottomSheet((close) => {
      close();
      setTimeout(() => {
        // Create a safe object with proper string conversions
        const voucherData = data.voucherItem?.value
          ? {
              vouchNm: String(data.voucherItem.value.vouchNm || ''),
              vouchTyNm: String(data.voucherItem.value.vouchTyNm || ''),
              vouchId: String(data.voucherItem.value.vouchId || ''),
              vouchAddres: String(data.voucherItem.value.contractAdres || ''),
              vouchBankCode: String(data.voucherItem.value.vouchBankCode || ''),
              insttWalletAdres: String(data.voucherItem.value.insttWalletAdres || ''),
              vouchTyCd: String(data.voucherItem.value.vouchTyCd || ''),
              vouchAmt: String(paymentCalcInfo?.vouchAmount || ''),
            }
          : {};
        onNext({
          ...context,
          ...voucherData,
        });
      }, 0);
    });
  });

  const handleSelectVoucher = async (option: SelectOption<VoucherItemDTO>) => {
    form.setValue('voucherItem', option);
  };

  const transactionLabel = getExchangeTransactionLabel(context.trnscTypeCd);

  return (
    <FormProvider {...form}>
      <div className="wrap bgw">
        <div className="content sub has-btm-btn">
          <ConfirmInfo amount={Number(context.trnscAmt)} phase={PhaseType.Confirm} transactionLabel={transactionLabel}>
            <div className="whitespace-pre-wrap">
              {i18n.t('text:fromX', { x: context?.placeNm ?? context?.placeSecret })}
            </div>
          </ConfirmInfo>
          <QueryErrorResetBoundary>
            {({ reset }) => (
              <ErrorBoundary fallback={FallbackErrorMessage} onReset={reset}>
                <Suspense fallback={<LoadingSpinner />}>
                  {context.placeNm && (
                    <>
                      <Controller
                        name="voucherItem"
                        control={form.control}
                        render={({ field }) => (
                          <VoucherList
                            selectedVoucher={field.value}
                            onSelectVoucher={handleSelectVoucher}
                            placeId={context.placeId}
                            aliasNm={context.isQrScan ? undefined : context.aliasNm}
                          />
                        )}
                      />
                      <PaymentDetails
                        depositAmount={Number(context.trnscAmt)}
                        vouchAmount={paymentCalcInfo?.vouchAmount || 0}
                        vcPayCalcAmt={paymentCalcInfo?.vcPayCalcAmt || 0}
                        vouchNm={form.watch('voucherItem.value.vouchNm') || ''}
                        showVoucherDetails={form.watch('voucherItem.value.vouchId') !== null}
                        vouchTyCd={form.watch('voucherItem.value.vouchTyCd') || ''}
                      />
                      <RefundPolicyInfo />
                    </>
                  )}
                </Suspense>
              </ErrorBoundary>
            )}
          </QueryErrorResetBoundary>
        </div>
        <div className="btm-btn-area" id="confirm-btn-area">
          <button type="button" className="btm-btn app" id="confirm-btn" onClick={handleSubmit}>
            {transactionLabel}하기
          </button>
        </div>
      </div>
    </FormProvider>
  );
};
